create extension if not exists pg_trgm;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 1 and 60),created_at timestamptz not null default now(),unique(user_id,name));
create table public.tags(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 1 and 40),unique(user_id,name));
create table public.prompts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null check(char_length(title) between 1 and 160),content text not null check(char_length(content) between 1 and 50000),description text,category_id uuid references public.categories(id) on delete set null,category_name text not null default 'Général',tags text[] not null default '{}',is_favorite boolean not null default false,is_archived boolean not null default false,usage_count integer not null default 0,last_used_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),client_updated_at timestamptz not null default now());
create table public.prompt_tags(prompt_id uuid references public.prompts(id) on delete cascade,tag_id uuid references public.tags(id) on delete cascade,primary key(prompt_id,tag_id));
create index prompts_user_updated_idx on public.prompts(user_id,updated_at desc);create index prompts_search_idx on public.prompts using gin((title||' '||content) gin_trgm_ops);create index tags_user_idx on public.tags(user_id);
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.tags enable row level security;alter table public.prompts enable row level security;alter table public.prompt_tags enable row level security;
create policy "own profile" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());create policy "own categories" on public.categories for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "own tags" on public.tags for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "own prompts" on public.prompts for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "own prompt tags" on public.prompt_tags for all using(exists(select 1 from public.prompts p where p.id=prompt_id and p.user_id=auth.uid())) with check(exists(select 1 from public.prompts p where p.id=prompt_id and p.user_id=auth.uid()));
alter publication supabase_realtime add table public.prompts,public.categories,public.tags,public.prompt_tags;
